// ── Grid container — szv over cols variants used in flex-grid.mdx ────────────
const colsVizSz = szv({
    base: { display: 'grid', w: 60, h: 24, gap: 2, border: true, borderColor: { color: 'emerald-400', op: 40 }, rounded: 'sm', p: 1 },
    variants: { cols: { '1': { gridCols: 1 }, '3': { gridCols: 3 } } },
