      </p>

      {/* Install block */}
      <div
        sz={{
          bg: { color: 'white', op: 90 },
          dark: { bg: { color: '#1e1e2aff', op: 40 }, borderColor: { color: 'white', op: 5 } },
          backdropBlur: 'xl',
          border: true,
          borderColor: { color: 'black', op: 5 },
          rounded: '3xl',
